import fs from 'node:fs';import assert from 'node:assert/strict';import{hostAdmissionFromEnv}from'./host-admission.bundle.mjs';
const host='0x2fcef48d6ad6919a6264074592b13855968b9f7be52c463764609a68af41447a';const env={ENCLAVE_CONTRACT_PINS_FILE:'C:/ProgramData/Enclave/nan-retirement/contract-pins.json',ENCLAVE_HOST_OWNERSHIP:'0xbbd885d3e9bc33609387bb9710e91c1905fe6ee7',ENCLAVE_HOST_REGISTRY_PIN:'0x868eb7fc5b5a84b2ff082eafc9bf40b7aac5ccac',ENCLAVE_HOST_CATALOG_PIN:'0x18419ca2b502d423a8de6269aeee171a378626e3',ENCLAVE_HOST_POLICY_DIR:'C:/ProgramData/Enclave/host-policy'};
const a=hostAdmissionFromEnv({hostId:host,env,rpc:['https://base-rpc.publicnode.com','https://base.drpc.org','https://mainnet.base.org'],addressBook:'0xab214342d5A490150A4A977063A2f88E21F80907'});
const state=await(await fetch('http://127.0.0.1:9600/v1/host/state')).json();const live=state.deployments.filter(d=>d.status==='running');assert.ok(live.length>=9);const out=[];
for(const d of live){const reason=await a.refusal({deploymentId:d.id,appRef:d.appRef});assert.equal(reason,null);out.push({deploymentId:d.id,allowed:true});}
const report={checkedAt:new Date().toISOString(),hostId:host,ownershipContract:env.ENCLAVE_HOST_OWNERSHIP,allowedRunningDeployments:out,productionMutated:false};fs.writeFileSync('C:/ProgramData/Enclave/nan-retirement/wallet-policy-preflight.json',JSON.stringify(report,null,2));console.log(JSON.stringify({status:'passed',runningDeployments:live.length,hostId:host}));
